-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla enemies con la categoria fauna y la columna drops).
--
-- Enemigos de Genshin Impact: los 569 del archivo del juego, divididos en
-- jefes (61), esbirros (285, de los que 80 son elites) y fauna (223).
--
-- Fuentes:
--   Yatta (gi.yatta.moe) -> nombre y descripcion oficiales en espanol e ingles,
--     faccion, resistencias, botin, consejos de combate e imagen.
--   Datos del propio juego (AnimeGameData, de Dimbreath) -> rango.
--
-- En Genshin no hay debilidades como en Honkai: cada enemigo tiene una
-- resistencia a cada elemento (normalmente 10%). En weaknesses van los
-- elementos con resistencia negativa, y en resistances las ocho, con las
-- inmunidades marcadas. Las versiones con resistencias distintas (Abismo,
-- eventos...) quedan en variants.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

--
-- PARTE 2 de 4 (140 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 4 partes, en cualquier orden.

insert into public.enemies (
  id, game_id, name, name_en, category, rank, faction, description, image_url, weaknesses, resistances, variants, skills, drops
)
values
  ('gi-enemy-26050601', 'genshin-impact', 'Dragarto de las Profundidades Primordial', 'Primordial Bathysmal Vishap', 'esbirro', 'elite', 'Bestias exóticas', 'Un Dragarto que vive en el fondo del mar.
Antes eran la raza dominante en el océano y, de hecho, los dragones dominaban el mundo entero en el pasado. Pero sus Siete Soberanos fueron derrotados por un poder procedente del cielo que acabó con todos ellos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Drake_Deepsea_Water.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":30},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":30},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":20},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[{"nombre":"Consejo de combate","descripcion":"Un depredador que hiberna en la oscuridad de las profundidades oceánicas. Parece que se ha adaptado a un poder desconocido del océano y puede usar otros elementos, aparte de Hydro. Al enfrentarse a sus enemigos, libera una poderosa lluvia purificadora que, al golpear a un personaje, hace que este pierda cierta cantidad de Energía Elemental. Si dicho personaje no tiene suficiente Energía, en su lugar perderá Vida.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Fragmento de hueso frágil","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112041.png","rareza":2},{"nombre":"Fragmento de hueso sólido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112042.png","rareza":3},{"nombre":"Fragmento de hueso fosilizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112043.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-26040101', 'genshin-impact', 'Dragarto Geo', 'Geovishap', 'esbirro', 'elite', 'Bestias exóticas', 'Un Dragarto Geo adulto.
Se dice que, tras un largo proceso de crecimiento, las Crías de Dragarto Geo mudan su coraza protectora y se convierten en Dragartos Geo. No obstante, tanto los adultos como las crías, así como los más poderosos Protodragartos Geo, yacieron dormidos durante muchos años bajo una montaña y no empezaron a estar activos hasta hace poco. Por tanto, no hay observaciones directas que confirmen esta teoría.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Drake_Rock.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":50}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un Dragarto Geo adulto muy fuerte. Cuando un personaje desvía sus ataques con un escudo y el escudo no se rompe, el Dragarto quedará paralizado debido al rebote...","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Fragmento de hueso frágil","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112041.png","rareza":2},{"nombre":"Fragmento de hueso sólido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112042.png","rareza":3},{"nombre":"Fragmento de hueso fosilizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112043.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-24030101', 'genshin-impact', 'Dragón de las Ruinas - Vigía aéreo', 'Ruin Drake: Skywatch', 'esbirro', 'elite', 'Autómatas', 'Una imponente máquina de combate con aspecto de dragón.
Cuenta la leyenda que se trata de un arma de guerra vestigio de una civilización ya extinta. Conserva la apariencia básica de un Dragarto, pero ha sido modificada para mejorar su rendimiento. En comparación con un Dragarto real, tiene una mayor capacidad de “absorber” y “contrarrestar” el poder de los elementos.
¿Cómo es que una civilización capaz de crear un arma de guerra de este tipo acabó por extinguirse?', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Gargoyle.png', '[]'::jsonb, '[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una máquina de las ruinas capaz de absorber energía y contraatacar. Durante el combate, el Dragón de las Ruinas - Vigía aéreo liberará cada cierto tiempo una peligrosa corriente de energía y, en función del tipo de daño elemental que haya recibido antes, aumentará su RES a ese elemento en concreto. En ciertas condiciones, los núcleos de varias partes de su cuerpo quedarán expuestos. Aprovecha esta oportunidad para atacar sus núcleos y, así, paralizarlo y anular su aumento de RES Elemental.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Contenedor del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112068.png","rareza":2},{"nombre":"Módulo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112069.png","rareza":3},{"nombre":"Perno del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112070.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-24030201', 'genshin-impact', 'Dragón de las Ruinas - Vigía terrestre', 'Ruin Drake: Earthguard', 'esbirro', 'elite', 'Autómatas', 'Una imponente máquina de combate con aspecto de dragón.
Cuenta la leyenda que se trata de un arma de guerra vestigio de una civilización ya extinta. Conserva la apariencia básica de un Dragarto, pero ha sido modificada para mejorar su rendimiento. En comparación con un Dragarto real, tiene una mayor capacidad de “absorber” y “contrarrestar” el poder de los elementos.
A juzgar por sus habilidades, la civilización que creó esta temible arma de guerra debió de ser extremadamente ambiciosa...', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Gargoyle.png', '[]'::jsonb, '[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una máquina de las ruinas capaz de absorber energía y contraatacar. Durante el combate, el Dragón de las Ruinas - Vigía terrestre liberará cada cierto tiempo una peligrosa corriente de energía y, en función del tipo de daño elemental que haya recibido antes, aumentará su RES a ese elemento en concreto. Cuando acumula fuerza para desatar la corriente de energía y cuando hace un ataque de embestida especial, el núcleo de su cabeza queda expuesto. Aprovecha esta oportunidad para atacar su núcleo y, así, paralizarlo y anular su aumento de RES Elemental.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Contenedor del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112068.png","rareza":2},{"nombre":"Módulo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112069.png","rareza":3},{"nombre":"Perno del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112070.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22020201', 'genshin-impact', 'Emisario del Abismo - Helada sombría', 'Abyss Herald: Frost Fall', 'esbirro', 'elite', 'Abismo', 'Una criatura de la Orden del Abismo que utiliza unos filos gélidos para combatir.
Así como los santos promulgan y glorifican los salmos que cantan desde el abismo, los emisarios corrigen los cánticos distorsionados y suprimen las disonancias.
Muchos son los que afirman que una sensación helada entumece el cuerpo cuando una espada lo atraviesa, pero la gelidez de este oscuro enemigo es capaz de congelar incluso el alma.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Invoker_Herald_Ice.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un monstruo de la Orden del Abismo con un poder oscuro que le permite controlar el hielo para combatir. Cuando algunos de sus ataques infligen daño, reduce el Aguante del personaje afectado.","tipo":"consejo","elemento":null}]'::jsonb, null),
  ('gi-enemy-22020101', 'genshin-impact', 'Emisario del Abismo - Rápidos malignos', 'Abyss Herald: Wicked Torrents', 'esbirro', 'elite', 'Abismo', 'Un monstruo perteneciente a la Orden del Abismo que utiliza el elemento Hydro para luchar.
Estas silenciosas sombras son las predecesoras del Abismo. Lo asolan todo con sus filos de agua, rompen en pedazos cualquier armadura y defensa, aplastan a los herejes y castigan cruelmente a los ignorantes más despreocupados.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Invoker_Herald_Water_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un monstruo de la Orden del Abismo que utiliza un poder oscuro para emplear torrentes entrelazados en la batalla. Cuando algunos de sus ataques infligen daño, incrementan el TdE de las habilidades del personaje que se encuentren en TdE.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Estatuilla oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112017.png","rareza":2},{"nombre":"Estatuilla del amanecer","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112018.png","rareza":3},{"nombre":"Estatuilla de las profundidades","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112019.png","rareza":4},{"nombre":"Rama seca de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112020.png","rareza":2},{"nombre":"Hojas secas de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112021.png","rareza":3},{"nombre":"Brotes de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112022.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-24020401', 'genshin-impact', 'Explorador de las Ruinas', 'Ruin Scout', 'esbirro', 'elite', 'Autómatas', 'Cuenta con mecanismos hechos a la medida y artilugios con funciones poco ortodoxas para cumplir con los objetivos más peculiares.
Se dice que esta máquina de guerra es el vestigio de una nación ya extinta. En comparación con los Guardianes de las Ruinas, de una complexión más robusta, el diseño de estos seres es más biomimético.
Se desconoce la razón por la cual su fisiología y movimiento imitan a los de una criatura de las profundidades marinas. Pero sea la razón que sea, no quieres ser presa de una de ellas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Apparatus_Enigma_BionicNettler.png', '[]'::jsonb, '[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Engranaje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112047.png","rareza":2},{"nombre":"Eje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112048.png","rareza":3},{"nombre":"Ojo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112049.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-26300201', 'genshin-impact', 'Filoceronte Radiante', 'Radiant Bladehorn', 'esbirro', 'elite', 'Bestias exóticas', 'Una bestia que ha terminado evolucionando de una forma única debido a la irradiación continuada del antiguo poder de la luna.
Se dice que antaño, cuando estas tierras fronterizas estaban envueltas en la sombra de la oscuridad, solo el gran rinoceronte podía traer de vuelta el poder que hacía que todo fluyera a este lugar al cargar con su manada... y que esa fue la única recompensa que les pidió la luz de la luna tras enviar su bendición.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Magbeast_Rhino.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":50},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un monstruo que ha terminado evolucionando de forma única debido a la irradiación del antiguo poder de la luna. Las Bestias Radiantes son capaces de emplear su fuerza innata para atrapar a sus enemigos en crisálidas radiantes. El efecto de la crisálida radiante hará que el daño infligido y la curación recibida se vean afectados.\nSin embargo, es posible eliminar el efecto de la crisálida restaurando por completo la Vida, tras lo que se obtendrá el efecto “desenredo”, el cual mejora las capacidades durante un breve periodo de tiempo. ¡Ese será el mejor momento para contraatacar!","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Trozo de hueso apagado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112131.png","rareza":2},{"nombre":"Restos centelleantes","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112132.png","rareza":3},{"nombre":"Hueso externo reluciente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112133.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-26300401', 'genshin-impact', 'Glaciolobo Radiante', 'Radiant Glacial Wolf', 'esbirro', 'elite', 'Bestias exóticas', 'Una bestia que ha terminado evolucionando de una forma única debido a la irradiación continuada del antiguo poder de la luna.
Cuenta la leyenda que, cuando una oscura calamidad arrasó con innumerables vidas, los bosques de las tierras fronterizas quedaron en completo silencio. En medio de tal quietud, el único sonido que rompía la calma era el aullido de los glaciolobos, una llamada a la luna. Noche tras noche, sus lamentos resonaban a través de la floresta desierta bajo la fría luz lunar.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Magbeast_Steppenwolf.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":50},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un monstruo que ha terminado evolucionando de forma única debido a la irradiación del antiguo poder de la luna. Las Bestias Radiantes son capaces de emplear su fuerza innata para atrapar a sus enemigos en crisálidas radiantes. El efecto de la crisálida radiante hará que el daño infligido y la curación recibida se vean afectados.\nSin embargo, es posible eliminar el efecto de la crisálida restaurando por completo la Vida, tras lo que se obtendrá el efecto “desenredo”, el cual mejora las capacidades durante un breve periodo de tiempo. ¡Ese será el mejor momento para contraatacar!","tipo":"consejo","elemento":null}]'::jsonb, null),
  ('gi-enemy-26140201', 'genshin-impact', 'Gólem Pretoriano', 'Praetorian Golem', 'esbirro', 'elite', 'Bestias exóticas', 'Una estatua móvil que representa a un guerrero dispuesto a apuntar con su espada a cualquiera que se atreva a invadir su territorio. Su poder es de origen desconocido, ¿será que está dominado por cierta alma? ¿O quizá sea cosa de magia?
Dicen que, en el pasado, hubo legiones de Gólems que conquistaron las regiones de aquellos que se refieren al Supramar como “hogar”, y quizá este guerrero haya pertenecido a dichas legiones. Las orgullosas torres e imponentes palacios que ahora descansan bajo las profundidades del océano atestiguan de nuevo a los que osan alterar los azares de la rueda del destino.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Golem_Legion.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un antiguo Gólem lleno de determinación que usa su robusto cuerpo de mármol para combatir. Si usas métodos efectivos contra Geo, podrás destruir sus defensas.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Empuñadura destrozada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112098.png","rareza":2},{"nombre":"Empuñadura hendida","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112099.png","rareza":3},{"nombre":"Empuñadura imperecedera","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112100.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-24110101', 'genshin-impact', 'Guardián de Dominio', 'Domain Keeper', 'esbirro', 'elite', 'Autómatas', 'Una creación de una de las sombras que emanó del todopoderoso ser primordial, así como el guardián que protege el Salón de Columnas del cielo.
Como guardián del Salón de Columnas del Espacio, aunque se le concedió un “ojo”, solo puede alabar las “formas ideales” eternas y verdaderas, incapaz de percibir la complejidad del mundo fenoménico, por lo que no se le considera igual a los ángeles. Si esta contradicción intrínseca fue un diseño racional de su creadora o si aquella a la que sirve tampoco comprende la voluntad del ser primordial, es algo que ya no se puede saber.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Watcher_Normal_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una creación de una de las sombras que emanó del todopoderoso ser primordial, y que es capaz de monitorear y contrarrestar ataques elementales. Durante el combate, el Guardián de Dominio entrará en el estado de “ojo de la necedad”, en el cual registrará por separado la cantidad de veces que recibe Daño Pyro/Hydro/Electro/Cryo. Cuando haya recibido 3 veces daño de alguno de dichos elementos, el Guardián de Dominio saldrá del estado de ojo de la necedad y adoptará la forma elemental correspondiente para aplicarse ese elemento a sí mismo y aumentar la RES Elemental correspondiente.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Empuñadura flamígera apagada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112140.png","rareza":2},{"nombre":"Empuñadura flamígera fracturada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112141.png","rareza":3},{"nombre":"Empuñadura flamígera engarzada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112142.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-24010101', 'genshin-impact', 'Guardián de las Ruinas', 'Ruin Guard', 'esbirro', 'elite', 'Autómatas', 'Una máquina de guerra muy antigua con forma humanoide.
Cuenta la leyenda que se trata de una máquina de guerra legada por un imperio que desapareció. Suele deambular por las ruinas de ciudades ya desaparecidas y atacar a los aventureros. Las investigaciones han descubierto que los Guardianes y las ruinas no comparten el mismo origen, e incluso miles de años los separan, así que... ¿por qué motivo se quedan en las ruinas y las defienden con todas sus fuerzas?', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Defender_Noner_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":70},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":70},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[{"nombre":"Consejo de combate","descripcion":"Los puntos débiles de los Guardianes de las Ruinas son su cabeza y el núcleo de energía en su espalda. Intenta atacarlos en esos puntos.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Dispositivo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112023.png","rareza":2},{"nombre":"Circuito del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112024.png","rareza":3},{"nombre":"Caldera del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112025.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21040101', 'genshin-impact', 'Hilichurl Errabundo Anemo', 'Anemo Hilichurl Rogue', 'esbirro', 'elite', 'Hilichurls', 'Un Hilichurl errante que no pertenece a ninguna tribu y que parece estar buscando los orígenes del destino de los de su especie, así como una gloria que ya se ha perdido.
Si los Hilichurls, que hablan una rudimentaria lengua y no tienen fuentes escritas, tuvieran poesía y leyendas propias, probablemente estos en concreto serían los protagonistas de esas historias.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hilistray_Wind.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":50},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un misterioso guerrero Hilichurl capaz de manipular hasta cierto punto el elemento Anemo. Durante el combate, utiliza Slimes Anemo para impulsarse y permanecer en el aire. Ataca a los Slimes Anemo cuando estos se hinchen para lograr derribar a este Hilichurl.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Flor encapullada de origen desconocido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112077.png","rareza":2},{"nombre":"Flor velada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112078.png","rareza":3},{"nombre":"Flor floreciente del trashumante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112079.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21040201', 'genshin-impact', 'Hilichurl Errabundo Hydro', 'Hydro Hilichurl Rogue', 'esbirro', 'elite', 'Hilichurls', 'Un Hilichurl errante que no pertenece a ninguna tribu y que deambula por el mundo como si se hubiera autoexiliado.
Guiado por el destino, ayuda a otros Hilichurls o asentamientos de Hilichurls que están en apuros y, tras hacerlo, prosigue con su viaje. Comparado con otros de su misma especie, este parece tener una mayor inteligencia.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hilistray_Water.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":50},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":50},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[{"nombre":"Consejo de combate","descripcion":"Un misterioso guerrero Hilichurl capaz de manipular hasta cierto punto el elemento Hydro. Durante el combate, utiliza Slimes Hydro para atacar disparando burbujas. Destruye los Slimes Hydro para que las burbujas reboten contra este Hilichurl.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Flor encapullada de origen desconocido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112077.png","rareza":2},{"nombre":"Flor velada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112078.png","rareza":3},{"nombre":"Flor floreciente del trashumante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112079.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-26290101', 'genshin-impact', 'Hurón Fraguacorazado', 'Furnace Shell Mountain Weasel', 'esbirro', 'elite', 'Bestias exóticas', 'Una antigua variante de hurón de montaña que vive en un entorno de flogisto especial y aislado del mundo exterior.
Una antigua bestia que se alimenta de criaturas ricas en flogisto y que acumula este combustible en su caparazón. Durante su larga vida en las ruinas de la Montaña Sagrada, parece que debido a su necesidad de estar cerca de flogisto, con el tiempo se han visto afectados por los Mecanismos Fuentenigma de su entorno, con los que han desarrollado una relación simbiótica.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_VolcanoWeasel.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":50},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una antigua bestia montañosa que vive en las ruinas de la Montaña Sagrada y que depende de los Mecanismos Fuentenigma. Durante el combate, el Hurón Fraguacorazado se mete bajo tierra y activa su “núcleo fuentenigma” para atacar periódicamente a su alrededor. En ese momento, infligir suficiente daño al núcleo fuentenigma hará que salga de la tierra. Sin embargo, ya que se encuentra bajo tierra, es posible que los Ataques Descendentes resulten más efectivos.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Fragmento de caparazón agrietado por el frío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112119.png","rareza":2},{"nombre":"Fragmento de caparazón con calor residual","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112120.png","rareza":3},{"nombre":"Fragmento de caparazón prismaflamígero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112121.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21020501', 'genshin-impact', 'Lawachurl Acorazado', 'Stonehide Lawachurl', 'esbirro', 'elite', 'Hilichurls', 'Un misterioso rey de los Hilichurls que deambula por las montañas rocosas.
Se trata de una criatura de gran tamaño a la que los demás Hilichurls llaman Lawa. El elemento Geo presente en el entorno se fusionó con su cuerpo, y su carne y su piel parecen hechas de roca.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Brute_Rock_None.png', '[]'::jsonb, '[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":70}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":70}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","rareza":2},{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","rareza":3},{"nombre":"Cuerno con cristal negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112016.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21020401', 'genshin-impact', 'Lawachurl Brazo Helado', 'Frostarm Lawachurl', 'esbirro', 'elite', 'Hilichurls', 'Un misterioso rey de los Hilichurls que deambula entre la nieve y la niebla.
Se trata de una criatura de gran tamaño a la que los demás Hilichurls llaman Lawa. Se ha ejercitado hasta desarrollar sus músculos al máximo y parece fundirse con el entorno, tan silencioso y majestuoso como los glaciares del Reino del Norte.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Brute_Ice_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":70},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":70},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":50},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","rareza":2},{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","rareza":3},{"nombre":"Cuerno con cristal negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112016.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21020801', 'genshin-impact', 'Lawachurl Electroyelmo', 'Thunderhelm Lawachurl', 'esbirro', 'elite', 'Hilichurls', 'Un misterioso rey de los Hilichurls que deambula en medio de la tempestad eléctrica.
Se trata de una criatura de gran tamaño a la que los demás Hilichurls llaman Lawa. Su cuerpo colosal está recubierto de energía Electro. De las fisuras de su piel brotan electrocristales de los que emana Energía Elemental.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Brute_Electric_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":70},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":70},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, null),
  ('gi-enemy-22120201', 'genshin-impact', 'Licopodio Abismático', 'Tenebrous Mimiflora', 'esbirro', 'elite', 'Abismo', 'Un monstruo del Abismo con forma de planta que ha llegado a este mundo desde la más profunda oscuridad de otro retorcido mundo.
Se dice que en los lugares corroídos por las olas oscuras crecen monstruos que se asemejan a plantas, pero cualquier parecido con estas es meramente superficial, pues la razón por la que adoptan este aspecto es para acercarse al mundo arbóreo, extraer de él los conceptos necesarios, analizarlos e imitarlos.
Algunos lunáticos afirman que aquellas cosas que se extienden como hojas en realidad son indicios de lo que podrían ser puertas que conducen a otros mundos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_TheAbyss_Rhizome.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un monstruo del abismo que ha llegado a este mundo desde la más profunda oscuridad de otro retorcido mundo. Durante el combate, el Licopodio Abismático creará una protección de vacío y algunos de sus ataques aplicarán el estado de “corrosión destructiva”, el cual hace que tu personaje en uso pierda Vida durante cierto periodo de tiempo. Usa una determinada cantidad de ataques elementales para romper su protección y, si usas ataques elementales de naturaleza noctámbula, podrás destruir más fácilmente sus defensas.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Brote refractor","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112116.png","rareza":2},{"nombre":"Hoja desconcertante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112117.png","rareza":3},{"nombre":"Nucleofolio difuso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112118.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-26260901', 'genshin-impact', 'Manifestación Wayob Abrasadora', 'Burning-Aflame Wayob Manifestation', 'esbirro', 'elite', 'Bestias exóticas', 'La Wayob en la que cree y adora la Tribu Plumaflora. Usa el poder de los tótems y las almas noctámbulas para manifestarse con esta forma.
Cuentan que hace mucho tiempo, las Manifestaciones Wayob tenían una apariencia muy diferente a la actual, pues tomaban una forma más tosca que se asemejaba más a la de una estatua de obsidiana. Sin embargo, desde que su silueta fue registrada en los pergaminos, han sufrido muy pocos cambios.
Los miembros de la Tribu Plumaflora creen que su Wayob tiene poder sobre las llamas y la combustión, además de saber controlar el flujo del calor y los ardientes vientos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Wayob_Flamingo.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":50},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Las Wayob, veneradas por las diversas tribus de Natlan, se manifiestan en forma de estos tótems de obsidiana. En combate, la Manifestación Wayob desplegará un área: momento de prueba que creará un escudo para sí misma y absorberá la Energía Elemental de todos los miembros del equipo que haya dentro de dicha área. No obstante, el daño de los personajes que se encuentren dentro del área aumentará considerablemente. Si rompes el escudo antes de que termine la duración del área, tus personajes recuperarán una gran cantidad de la Energía Elemental perdida. Si no lo consigues, la Manifestación Wayob generará una protección elemental en función de la cantidad de escudo restante.","tipo":"consejo","elemento":null}]'::jsonb, null),
  ('gi-enemy-26261101', 'genshin-impact', 'Manifestación Wayob Azotatruenos', 'Thundering Wayob Manifestation', 'esbirro', 'elite', 'Bestias exóticas', 'La Wayob en la que cree y adora la Comunidad de la Feracidad. Su forma se manifiesta sobre la tierra a través del poder de los tótems y las almas noctámbulas.
Según las leyendas de la Comunidad de la Feracidad, esta Wayob ha adoptado muchas formas para competir con los famosos luchadores de la tribu en la oscuridad previa al amanecer, de manera que eran incapaces de ver el rostro del otro. Sin embargo, la mayoría de estas competiciones terminaron en empate.
Los habitantes de la Comunidad de la Feracidad creen que su Wayob tiene el poder de controlar el trueno y la velocidad, así como la capacidad de traer abundancia a la tierra.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Wayob_Bisonsaurus.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":50},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Las Wayob, veneradas por las diversas tribus de Natlan, se manifiestan en forma de estos tótems de obsidiana. En combate, la Manifestación Wayob desplegará un área: momento de prueba que creará un escudo para sí misma y absorberá la Energía Elemental de todos los miembros del equipo que haya dentro de dicha área. No obstante, el daño de los personajes que se encuentren dentro del área aumentará considerablemente. Si rompes el escudo antes de que termine la duración del área, tus personajes recuperarán una gran cantidad de la Energía Elemental perdida. Si no lo consigues, la Manifestación Wayob generará una protección elemental en función de la cantidad de escudo restante.","tipo":"consejo","elemento":null}]'::jsonb, null),
  ('gi-enemy-26260101', 'genshin-impact', 'Manifestación Wayob Cavernaria', 'Rock-Cavernous Wayob Manifestation', 'esbirro', 'elite', 'Bestias exóticas', 'La Wayob en la que creen y adoran los Vástagos del Eco. Usa el poder de los tótems y las almas noctámbulas para manifestarse con esta forma. En el saber de las tribus de Natlan, las Wayob viven en el Reino de la Noche y no tienen una forma fija, ya que se adhieren a cualquier objeto para guiar a la gente perdida de las tribus. Entre estos seres, las Manifestaciones Wayob son aún más especiales, pues toman la forma de los tótems para mostrarse y suelen tener una misión importante que llevar a cabo.
Los Vástagos del Eco creen que su Wayob tiene el poder de moldear picos y valles y puede controlar los ecos que produce el choque entre rocas y peñascos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Wayob_Drillhead.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":50}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Las Wayob, veneradas por las diversas tribus de Natlan, se manifiestan en forma de estos tótems de obsidiana. En combate, la Manifestación Wayob desplegará un área: momento de prueba que creará un escudo para sí misma y absorberá la Energía Elemental de todos los miembros del equipo que haya dentro de dicha área. No obstante, el daño de los personajes que se encuentren dentro del área aumentará considerablemente. Si rompes el escudo antes de que termine la duración del área, tus personajes recuperarán una gran cantidad de la Energía Elemental perdida. Si no lo consigues, la Manifestación Wayob generará una protección elemental en función de la cantidad de escudo restante.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Fragmento de voluntad quebrantada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112107.png","rareza":2},{"nombre":"Ídolo de voluntad manifiesta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112108.png","rareza":3},{"nombre":"Sello de voluntad patrullera","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112109.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-26260201', 'genshin-impact', 'Manifestación Wayob Contrafluyente', 'Flow-Inverted Wayob Manifestation', 'esbirro', 'elite', 'Bestias exóticas', 'La Wayob en la que cree y adora el Pueblo de los Manantiales. Usa el poder de los tótems y las almas noctámbulas para manifestarse con esta forma.
Las Wayob son la creencia que se fue formando a raíz de las tribus y los tótems de obsidiana después de que los habitantes de Natlan empezaran a comunicarse con el Reino de la Noche. Es una consciencia con pensamiento colectivo, así como el hogar de las almas de los ancestros.
Los miembros del Pueblo de los Manantiales creen que su Wayob tiene el poder de manipular la marea y las olas del mar, y puede controlar los cambios que se producen en las aguas muertas y aguas corrientes.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Wayob_Mosasaurus.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":50},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Las Wayob, veneradas por las diversas tribus de Natlan, se manifiestan en forma de estos tótems de obsidiana. En combate, la Manifestación Wayob desplegará un área: momento de prueba que creará un escudo para sí misma y absorberá la Energía Elemental de todos los miembros del equipo que haya dentro de dicha área. No obstante, el daño de los personajes que se encuentren dentro del área aumentará considerablemente. Si rompes el escudo antes de que termine la duración del área, tus personajes recuperarán una gran cantidad de la Energía Elemental perdida. Si no lo consigues, la Manifestación Wayob generará una protección elemental en función de la cantidad de escudo restante.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Fragmento de voluntad quebrantada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112107.png","rareza":2},{"nombre":"Ídolo de voluntad manifiesta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112108.png","rareza":3},{"nombre":"Sello de voluntad patrullera","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112109.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-26260801', 'genshin-impact', 'Manifestación Wayob Gélida', 'Biting-Cold Wayob Manifestation', 'esbirro', 'elite', 'Bestias exóticas', 'La Wayob en la que creen y adoran los Augures Vientonocturno. Usa el poder de los tótems y las almas noctámbulas para manifestarse con esta forma.
Los Augures Vientonocturno probaron multitud de medios para comunicarse con el Reino de la Noche. Finalmente, descubrieron que el material que les permitía establecer la conexión más estable con las Wayob era la obsidiana. Puede que esto explique por qué, a través de las eras, las Manifestaciones Wayob han tomado una forma que se asemeja a la de una estatua. Los Augures Vientonocturno creen que su Wayob posee la capacidad de controlar los procesos de congelación y cristalización, además de dominar tanto lo sólido como lo cambiante.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Wayob_Shamansaurus.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":50},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Las Wayob, veneradas por las diversas tribus de Natlan, se manifiestan en forma de estos tótems de obsidiana. En combate, la Manifestación Wayob desplegará un área: momento de prueba que creará un escudo para sí misma y absorberá la Energía Elemental de todos los miembros del equipo que haya dentro de dicha área. No obstante, el daño de los personajes que se encuentren dentro del área aumentará considerablemente. Si rompes el escudo antes de que termine la duración del área, tus personajes recuperarán una gran cantidad de la Energía Elemental perdida. Si no lo consigues, la Manifestación Wayob generará una protección elemental en función de la cantidad de escudo restante.","tipo":"consejo","elemento":null}]'::jsonb, null),
  ('gi-enemy-26260301', 'genshin-impact', 'Manifestación Wayob Raudifolia', 'Foliar-Swift Wayob Manifestation', 'esbirro', 'elite', 'Bestias exóticas', 'La Wayob en la que creen y adoran los Retoños Arbóreos. Usa el poder de los tótems y las almas noctámbulas para manifestarse con esta forma.
En las historias de los cuentacuentos, las Manifestaciones Wayob suelen aparecer como emisarias de una prueba o guías del Reino de la Noche. Hubo una vez un soldado sauriocoronado que afirmó haber luchado contra una Manifestación Wayob mientras estaba en trance y practicaba sus habilidades. Según él, gracias a ello obtuvo una mayor comprensión de las cosas.
Los Retoños Arbóreos creen que su Wayob tiene el poder de controlar el crecimiento de los frutos, las hojas de las plantas y las raíces de los cultivos, y puede dibujar patrones en los nervios de las hojas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Wayob_Hookwalker.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":50},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Las Wayob, veneradas por las diversas tribus de Natlan, se manifiestan en forma de estos tótems de obsidiana. En combate, la Manifestación Wayob desplegará un área: momento de prueba que creará un escudo para sí misma y absorberá la Energía Elemental de todos los miembros del equipo que haya dentro de dicha área. No obstante, el daño de los personajes que se encuentren dentro del área aumentará considerablemente. Si rompes el escudo antes de que termine la duración del área, tus personajes recuperarán una gran cantidad de la Energía Elemental perdida. Si no lo consigues, la Manifestación Wayob generará una protección elemental en función de la cantidad de escudo restante.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Fragmento de voluntad quebrantada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112107.png","rareza":2},{"nombre":"Ídolo de voluntad manifiesta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112108.png","rareza":3},{"nombre":"Sello de voluntad patrullera","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112109.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21020601', 'genshin-impact', 'Mitachurl con Escudo Cryo', 'Ice Shieldwall Mitachurl', 'esbirro', 'elite', 'Hilichurls', 'Un Hilichurl muy grande que utiliza un escudo de hielo en la batalla.
En general, los organismos grandes y activos necesitan consumir muchas calorías para sobrevivir. Por este motivo, El Musk propuso el “índice Mitachurl”, que calcula la abundancia y estabilidad del acceso a los alimentos de una población concreta de Hilichurls según la proporción de Mitachurls que haya entre ellos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Brute_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Mitachurl que utiliza un escudo Cryo para protegerse. Durante el Clima glacial, el escudo Cryo se regenera. Rompe sus defensas atacando con Pyro u otros elementos que reaccionan con Cryo.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","rareza":2},{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","rareza":3},{"nombre":"Cuerno con cristal negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112016.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21020101', 'genshin-impact', 'Mitachurl con Escudo de Madera', 'Wooden Shieldwall Mitachurl', 'esbirro', 'elite', 'Hilichurls', 'Un Hilichurl muy grande con experiencia en miles de batallas.
Al combatir utiliza un escudo muy resistente hecho con Slimes Dendro.
Disfruta de una posición elevada en la tribu gracias a sus fuertes músculos, su brillante melena, su capacidad de devorar varios kilos de carne en una comida y su habilidad para ahuyentar aventureros.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Brute_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Ataca y se defiende usando un gran escudo de madera, que tiene atributos Dendro. Tal vez haya una manera de prenderle fuego...","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","rareza":2},{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","rareza":3},{"nombre":"Cuerno con cristal negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112016.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21020301', 'genshin-impact', 'Mitachurl con Escudo de Piedra', 'Rock Shieldwall Mitachurl', 'esbirro', 'elite', 'Hilichurls', 'Un Hilichurl muy grande con un escudo de piedra.
Los combates y la carne son las dos cosas más importantes para los Hilichurls, pues es lo que los hace más fuertes.
Estos guerreros grandes y poderosos pueden comer más carne, pelear en más batallas y sostener estos casi indestructibles escudos de piedra.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Brute_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Se protege a sí mismo usando un escudo con atributos Geo (a diferencia de los escudos de madera de los Mitachurls). Usa ataques pesados como Ataques Geo, mandobles y explosiones para romper el escudo.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","rareza":2},{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","rareza":3},{"nombre":"Cuerno con cristal negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112016.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21020201', 'genshin-impact', 'Mitachurl con Hacha de Fuego', 'Blazing Axe Mitachurl', 'esbirro', 'elite', 'Hilichurls', 'Un Hilichurl muy grande con un hacha de mango largo.
Un Hilichurl con un gran poder destructivo que ataca con amplios movimientos y utiliza un Slime Pyro para añadir fuego a su hacha.
Normalmente, si se usa el fuego repetidas veces para templar un arma, el acero acaba debilitándose y el filo se rompe con facilidad. Pero los Mitachurls con Hacha de Fuego son tan fuertes que, si su hacha no tiene filo, la pueden usar como martillo y seguir siendo igual de peligrosos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Brute_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","rareza":2},{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","rareza":3},{"nombre":"Cuerno con cristal negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112016.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-21020701', 'genshin-impact', 'Mitachurl con Hacha Electro', 'Crackling Axe Mitachurl', 'esbirro', 'elite', 'Hilichurls', 'Un Hilichurl muy grande con un hacha de mango largo.
Un Hilichurl con un gran poder destructivo que ataca con amplios movimientos y utiliza un Slime Electro para electrizar su hacha.
Su hacha de acero es un excelente conductor. A los ojos de los Hilichurls comunes y corrientes, el imponente Mitachurl que invoca el poder del rayo con su temeraria hacha Electro, es considerado como un héroe.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Brute_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, null),
  ('gi-enemy-20020101', 'genshin-impact', 'Ojo de la Tormenta', 'Eye of the Storm', 'esbirro', 'elite', 'Seres elementales', 'Una forma generada a partir de nódulos Anemo de alta calidad.
La formación del Ojo de la Tormenta indica las obstrucciones de las líneas ley elementales de un lugar, ya que se condensa a partir de ellas. El Ojo de la Tormenta blande el poder de las tempestades y puede hacer volar por los aires a todos aquellos a su alrededor. Tal vez también simboliza las enfermedades del cielo y la tierra.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Elemental_Wind_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un enemigo peligroso que puede invocar una Esfera de Huracán para infligir Daño continuo en el AdE. Intenta utilizar la corriente de viento generada en el centro para despegar del suelo.","tipo":"consejo","elemento":null}]'::jsonb, null),
  ('gi-enemy-26310401', 'genshin-impact', 'Oso Quimérico Cornudo', 'Chimeric Horned Bear', 'esbirro', 'elite', 'Bestias exóticas', 'Un monstruo quimérico producto de la bioalquimia que posee una forma sumamente peculiar.
No fue creado según el diseño de nadie, sino que se formó a partir de la combinación autónoma de segmentos con vida, lo que le otorgó la capacidad casi milagrosa de usar el poder elemental con naturalidad.
Cuando la vida se fragmenta hasta quedar reducida a meros segmentos, ¿hay alguna voluntad o fuerza suprema que los ayude a crecer siguiendo un misterioso plan?
Quizás, a día de hoy, ya no quede nadie capaz de responder a eso.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Chimera_BearDeer.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":30},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"En Snezhnaya, muchos de los enemigos tendrán dificultades para usar sus habilidades al verse afectados por las reacciones de Destello Estelar.\n¡Aprovecha dichas reacciones para obtener la ventaja en el combate!","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Semilla quimérica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112149.png","rareza":1},{"nombre":"Célula quimérica simbiótica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112150.png","rareza":2},{"nombre":"Organismo quimérico primigenio","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112151.png","rareza":3}]'::jsonb),
  ('gi-enemy-24020101', 'genshin-impact', 'Patrullero de las Ruinas', 'Ruin Cruiser', 'esbirro', 'elite', 'Autómatas', 'Cuenta con mecanismos hechos a la medida y artilugios con funciones poco ortodoxas para cumplir con los objetivos más peculiares.
Se dice que esta máquina de guerra es el vestigio de una nación ya extinta. En comparación con los Guardianes de las Ruinas, de una complexión más robusta, el diseño de estos seres es más biomimético. Su diseño modular y forma de combate imitan a los de una colmena, capaz de adquirir cualquier forma y lanzar ataques en todas direcciones.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Apparatus_Enigma_BionicDrone.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Engranaje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112047.png","rareza":2},{"nombre":"Eje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112048.png","rareza":3},{"nombre":"Ojo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112049.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-23085101', 'genshin-impact', 'Patrullero Terrestre - Modelo puntero de asalto multifuncional', 'Cutting Edge All-Purpose Storm Landcruiser', 'esbirro', 'elite', 'Fatui', 'Un Patrullero Terrestre de élite que cuenta con un equilibrio entre tecnología puntera, costes de producción e índice de despliegue, lo que confiere un inmenso poder destructivo a cualquier secuencia de combate. Es el eje clave de la primera línea de batalla.
Este Modelo de asalto multifuncional combina una ametralladora automática de varios cañones con dos cuchillas giratorias de corto alcance, lo que le permite luchar contra sus oponentes a cualquier distancia, mientras que, con los pesados lanzagranadas de sus brazos, puede destruir búnkeres y privar al enemigo de cualquier tipo de protección. Según las directrices de combate redactadas conjuntamente entre los Fatui y la Real Academia Militar, estos Patrulleros Terrestres deben contar con el apoyo de todas las unidades cercanas al atacar para abrir rápidamente una brecha en las líneas enemigas, lo que le permitirá seguir atacando hasta desmoronar las defensas enemigas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Fatuimecha_CoreC_MoveD_AttackA_AttackC_AttackB_Electric.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un transporte militar que patrulla por tierra y que posee gran capacidad armamentística. Tras ciertas modificaciones, es capaz de hacer uso de sus funcionalidades especiales gracias al kuuvahki. Atácalo cierta cantidad de veces con reacciones de Electrocargado o Electrocargado Lunar para detenerlo cuando esté empleando el kuuvahki.\nComo depende del kuuvahki, tal vez al usar dicha energía puedas atacarlo de forma increíblemente efectiva.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Eje dañado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112122.png","rareza":1},{"nombre":"Eje reforzado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112123.png","rareza":2},{"nombre":"Eje refinado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112124.png","rareza":3}]'::jsonb),
  ('gi-enemy-23085201', 'genshin-impact', 'Patrullero Terrestre - Modelo puntero de exploración multifuncional', 'Cutting Edge All-Purpose Scout Landcruiser', 'esbirro', 'elite', 'Fatui', 'Un Patrullero Terrestre de élite que cuenta con un equilibrio entre tecnología puntera, costes de producción e índice de despliegue, lo que confiere un inmenso poder destructivo a cualquier secuencia de combate. Es el eje clave de la primera línea de batalla.
Este Modelo de exploración multifuncional también está diseñado para el combate a larga y corta distancia, y no solo lidera escuadrones de Patrulleros Terrestres de Modelo de exploración, sino que también proporciona apoyo cercano a los Modelos de asalto multifuncionales en batallas de alta intensidad, como cruzar trincheras anti-Patrulleros Terrestres o destruir los puntos fuertes del enemigo. También es capaz de seguir el ritmo de la vanguardia mientras esta avanza, para luego desviarse hacia los flancos y atacar rápidamente a los objetivos clave situados en la retaguardia del enemigo.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Fatuimecha_CoreC_MoveC_AttackD_AttackC_AttackB_Water.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un transporte militar que patrulla por tierra y que posee gran capacidad armamentística. Tras ciertas modificaciones, es capaz de hacer uso de sus funcionalidades especiales gracias al kuuvahki. Atácalo cierta cantidad de veces con reacciones de Electrocargado o Electrocargado Lunar para detenerlo cuando esté empleando el kuuvahki.\nComo depende del kuuvahki, tal vez al usar dicha energía puedas atacarlo de forma increíblemente efectiva.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Eje dañado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112122.png","rareza":1},{"nombre":"Eje reforzado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112123.png","rareza":2},{"nombre":"Eje refinado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112124.png","rareza":3}]'::jsonb),
  ('gi-enemy-23085301', 'genshin-impact', 'Patrullero Terrestre - Modelo puntero de fuego terrestre', 'Cutting Edge Fire Support Ground Effect Landcruiser', 'esbirro', 'elite', 'Fatui', 'Un Patrullero Terrestre de élite que cuenta con un equilibrio entre tecnología puntera, costes de producción e índice de despliegue, lo que confiere un inmenso poder destructivo a cualquier secuencia de combate. Es el eje clave de la primera línea de batalla.
Tras equiparle un motor a reacción de alta eficiencia, este Patrullero Terrestre ha adquirido la capacidad de utilizar múltiples armas, lo que le permite enviar esta considerable potencia de fuego a cualquier lugar del campo de batalla de manera oportuna. Por ello, según las directrices de combate redactadas conjuntamente entre los Fatui y la Real Academia Militar, estos Patrulleros deben organizarse como una “fuerza de reacción rápida” en batallas a gran escala, con el fin de protegerse contra las incursiones o contraataques enemigos y aprovechar la ventaja si la batalla se desarrolla de manera favorable. Naturalmente, todos los Patrulleros Terrestres punteros tienen la capacidad de operar de forma independiente y, en misiones largas, pueden ser el núcleo de un pequeño escuadrón, lo que maximizará la potencia de fuego de toda clase de unidades Fatui.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Fatuimecha_CoreC_MoveF_AttackB_Fire.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un transporte militar que patrulla por tierra y que posee gran capacidad armamentística. Tras ciertas modificaciones, es capaz de hacer uso de sus funcionalidades especiales gracias al kuuvahki. Atácalo cierta cantidad de veces con reacciones de Electrocargado o Electrocargado Lunar para detenerlo cuando esté empleando el kuuvahki.\nComo depende del kuuvahki, tal vez al usar dicha energía puedas atacarlo de forma increíblemente efectiva.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Eje dañado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112122.png","rareza":1},{"nombre":"Eje reforzado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112123.png","rareza":2},{"nombre":"Eje refinado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112124.png","rareza":3}]'::jsonb),
  ('gi-enemy-22140101', 'genshin-impact', 'Pescador de las Profundidades Insondables', 'Fisher of Hidden Depths', 'esbirro', 'elite', 'Abismo', 'Una criatura del Abismo que se infiltra a través de fisuras en las profundidades insondables, cruzando a este mundo desde lugares desconocidos.
Hace mucho tiempo, un antiguo filósofo describió a los humanos como “bípedos sin plumas”, usando una expresión tan sencilla para distinguir a la humanidad de los animales y así afirmar la superioridad de los primeros. De alguna forma, estas bestias inmortales que vagan por el silencioso vacío cósmico, tienen escamas en vez de plumas y usan sus ganchudos picos para devorar la biomasa de los distintos mundos también podrían ajustarse a la misma definición simplista de “humanos”.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Lloigor_Sub.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una manada de monstruos que ha emergido a través de una fisura de las profundidades insondables. Cuando haya múltiples Pescadores de las Profundidades Insondables en el campo, sus vínculos mutuos formarán un “escudo insondable” que solo podrá romperse con ataques elementales o daño de reacciones. El daño de Reacciones Lunares será especialmente efectivo para destruir dicho escudo.","tipo":"consejo","elemento":null},{"nombre":"Consejo de combate","descripcion":"Cuando el escudo insondable de uno de los Pescadores de las Profundidades Insondables se rompa, el vínculo compartido entre ellos hará que todos los escudos de la manada se hagan añicos. Después, los demás miembros quedarán agrupados alrededor del Pescador de las Profundidades Insondables que perdió su escudo.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Ojo fracturado de las profundidades insondables","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112137.png","rareza":2},{"nombre":"Núcleo aberrante de las profundidades insondables","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112138.png","rareza":3},{"nombre":"Pico de las profundidades insondables","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112139.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-24090601', 'genshin-impact', 'Pionera Fuentenigma de Matrices de Observación Navegadora', 'Precursor''s Secret Source Matrix of Overseer Network', 'esbirro', 'elite', 'Autómatas', 'Una antigua máquina atrapada entre las ruinas de la Luna. Con el suficiente tiempo, hasta las máquinas más resistentes y fiables acaban perdiendo el propósito que les otorgaron sus creadores, y se convierten en objetos que atacan y eliminan a cualquier ser viviente que se atreva a pisar el suelo que defienden.
En los registros de una antigua civilización que se perdió hace mucho tiempo, estas máquinas descontroladas fueron bautizadas en su día con el nombre de “Ur-Namrasit-Tilimutu-Babbar”, que significa “aquel que alza la luz en la oscuridad”. Anhelando llegar al vasto mar de estrellas, los líderes de los “pioneros” grabaron sus palabras más sinceras en unos patrones dorados, con la esperanza de que, ayudados por estos asistentes, sus sucesores pudieran encender la luz que realmente iluminaría el universo.
Sin embargo, esa luz nunca llegó a “alzarse” para nadie, y estas máquinas “de control” no lograron ver a los dueños a los que debían servir. Ahora, varadas en estas ruinas, no son más que el último vestigio descontrolado de un ideal que se perdió hace mucho tiempo.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Monitor_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un Mecanismo Fuentenigma capaz de operar en el mar de estrellas, lejos de las líneas ley. Durante el combate, la Pionera Fuentenigma de Matrices de Observación Navegadora usará energía lunarcaica para activar un campo de convergencia y reunir poder Hydro para fortalecerse. Congélala en este momento y usa Rompehielo, Derretido y otras Reacciones Elementales para romper el hielo y detener el funcionamiento del campo de convergencia.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Hierro lunar fracturado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112143.png","rareza":2},{"nombre":"Hierro lunar mermado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112144.png","rareza":3},{"nombre":"Hierro lunar inmaculado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112145.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22110201', 'genshin-impact', 'Protofisurador Quebrantarrocas', 'Shatterstone Breacher Primus', 'esbirro', 'elite', 'Abismo', 'Una extraña criatura que mora principalmente en el cuerpo de Elynas.
Recibe un potente choque al entrar en contacto con energía ousía o pneuma, por lo que, aunque no posea un instinto muy agresivo, es un buen método para ahuyentar a Protofisuradores como este.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Ovacua_Order_02.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":30}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una forma de vida muy extraña que no tiene nada en común con los demás seres de este mundo. Durante el combate, entra en estado de estrés para atacar continuamente con rocas represivas mientras se defiende con una protección Geo. Si logras romper su protección, lo paralizarás durante un tiempo. Además de mediante Reacciones Elementales, también puedes derribar las defensas de un Protofisurador con ataques de energía ousía o pneuma.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Núcleo de la fisura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112089.png","rareza":2},{"nombre":"Sinapsis extrínseca","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112090.png","rareza":3},{"nombre":"Núcleo vital de otro mundo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112091.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22110101', 'genshin-impact', 'Protofisurador Quebrantarrocas Gigante', 'Large Shatterstone Breacher Primus', 'esbirro', 'elite', 'Abismo', 'Una extraña criatura que mora principalmente en el cuerpo de Elynas.
Según la sabiduría de las melusinas, los Protofisuradores no son criaturas peligrosas. Al contrario, las consideran incluso adorables.
Al parecer, la percepción visual de las melusinas dista bastante de la de los humanos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Ovacua_Order_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":50}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una forma de vida muy extraña que no tiene nada en común con los demás seres de este mundo. Durante el combate, entra en estado de estrés para atacar continuamente con rocas represivas mientras se defiende con una protección Geo. Si logras romper su protección, lo paralizarás durante un tiempo. Además de mediante Reacciones Elementales, también puedes derribar las defensas de un Protofisurador con ataques de energía ousía o pneuma.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Núcleo de la fisura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112089.png","rareza":2},{"nombre":"Sinapsis extrínseca","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112090.png","rareza":3},{"nombre":"Núcleo vital de otro mundo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112091.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22110401', 'genshin-impact', 'Protofisurador Sobrecrecido', 'Overgrown Breacher Primus', 'esbirro', 'elite', 'Abismo', 'Una extraña criatura que mora principalmente en el cuerpo de Elynas.
Los primeros Protofisuradores registrados en Fontaine aparecieron poco después de la catástrofe que ocurrió. Fue entonces también cuando se registraron los primeros casos de Protofisuradores atacando y protegiendo a los humanos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Ovacua_Chaos_02.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":30},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una forma de vida muy extraña que no tiene nada en común con los demás seres de este mundo. Durante el combate, entra en estado de estrés para atacar continuamente con proyectiles enredadores mientras se defiende con una protección Dendro. Si logras romper su protección, lo paralizarás durante un tiempo. Además de mediante Reacciones Elementales, también puedes derribar las defensas de un Protofisurador con ataques de energía ousía o pneuma.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Núcleo de la fisura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112089.png","rareza":2},{"nombre":"Sinapsis extrínseca","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112090.png","rareza":3},{"nombre":"Núcleo vital de otro mundo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112091.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22110301', 'genshin-impact', 'Protofisurador Sobrecrecido Gigante', 'Large Overgrown Breacher Primus', 'esbirro', 'elite', 'Abismo', 'Una extraña criatura que mora principalmente en el cuerpo de Elynas.
Los Protofisuradores superan los límites del conocimiento actual, ya que, basándose en sus características biológicas, no pertenecen a ninguna especie animal, vegetal, fúngica o elemental. Por ello, los eruditos de Sumeru se hallan absortos en un acalorado debate sobre la verdadera naturaleza de estas criaturas. Tal fue el desconcierto que la Academia prohibió por completo el estudio de este tema. El motivo fue que, al igual que ocurre con la definición y esencia del lenguaje, los Protofisuradores escapan a la compresión actual del ser humano y, por tanto, no sería posible llegar a una conclusión precisa sobre ellos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Ovacua_Chaos_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":50},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una forma de vida muy extraña que no tiene nada en común con los demás seres de este mundo. Durante el combate, entra en estado de estrés para atacar continuamente con proyectiles enredadores mientras se defiende con una protección Dendro. Si logras romper su protección, lo paralizarás durante un tiempo. Además de mediante Reacciones Elementales, también puedes derribar las defensas de un Protofisurador con ataques de energía ousía o pneuma.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Núcleo de la fisura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112089.png","rareza":2},{"nombre":"Sinapsis extrínseca","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112090.png","rareza":3},{"nombre":"Núcleo vital de otro mundo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112091.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22050201', 'genshin-impact', 'Sabueso Acechador Eléctrico', 'Thundercraven Rifthound', 'esbirro', 'elite', 'Abismo', 'Una bestia de sangre demoniaca creada por Oro y capaz de corroer las fronteras del mundo.
En el pasado, sembraron el caos en todo el continente hasta que fueron erradicados cuando la gente se opuso a ellos y les dio caza. Sin embargo, este grupo de lobos negros ha vuelto a aparecer hace poco, y ahora amenaza la Aldea Aguaclara y el Reino de los Lobos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hound_Riftstalker_Electric.png', '[]'::jsonb, '[{"elemento":"Físico","valor":25},{"elemento":"Pyro","valor":25},{"elemento":"Hydro","valor":25},{"elemento":"Anemo","valor":25},{"elemento":"Electro","valor":25},{"elemento":"Dendro","valor":25},{"elemento":"Cryo","valor":25},{"elemento":"Geo","valor":25}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":25},{"elemento":"Pyro","valor":25},{"elemento":"Hydro","valor":25},{"elemento":"Anemo","valor":25},{"elemento":"Electro","valor":25},{"elemento":"Dendro","valor":25},{"elemento":"Cryo","valor":25},{"elemento":"Geo","valor":25}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Pyro","valor":20},{"elemento":"Hydro","valor":20},{"elemento":"Anemo","valor":20},{"elemento":"Electro","valor":20},{"elemento":"Dendro","valor":20},{"elemento":"Cryo","valor":20},{"elemento":"Geo","valor":20}]}]'::jsonb, '[{"nombre":"Consejo de combate","descripcion":"Parece la versión adulta de un Cachorro Acechador, pero en realidad, a día de hoy sigue siendo un enigma si estos monstruos son capaces de crecer o no. Los ataques de los Sabuesos Acechadores aplican el estado acumulable de corrosión, el cual hace que todos los miembros del equipo pierdan Vida continuamente. Además, cuando reciben un ataque elemental, entran en el estado de devoración elemental, con el que se vuelven extremadamente violentos a costa de reducir su propia resistencia a ese elemento.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Garra oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112056.png","rareza":2},{"nombre":"Garra afilada oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112057.png","rareza":3},{"nombre":"Garra fantasmal oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112058.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22050101', 'genshin-impact', 'Sabueso Acechador Lítico', 'Rockfond Rifthound', 'esbirro', 'elite', 'Abismo', 'Una bestia de sangre demoniaca capaz de corroer las fronteras del mundo. Fue creada por Oro.
Muestra cierto comportamiento biológico parecido al de los lobos. Tal vez sientan envidia de ellos, que son sus parientes más cercanos, y sueñen con reemplazarlos algún día.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hound_Riftstalker_Rock.png', '[]'::jsonb, '[{"elemento":"Físico","valor":25},{"elemento":"Pyro","valor":25},{"elemento":"Hydro","valor":25},{"elemento":"Anemo","valor":25},{"elemento":"Electro","valor":25},{"elemento":"Dendro","valor":25},{"elemento":"Cryo","valor":25},{"elemento":"Geo","valor":25}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":25},{"elemento":"Pyro","valor":25},{"elemento":"Hydro","valor":25},{"elemento":"Anemo","valor":25},{"elemento":"Electro","valor":25},{"elemento":"Dendro","valor":25},{"elemento":"Cryo","valor":25},{"elemento":"Geo","valor":25}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[{"nombre":"Consejo de combate","descripcion":"Parece la versión adulta de un Cachorro Acechador, pero en realidad, a día de hoy sigue siendo un enigma si estos monstruos son capaces de crecer o no. Los ataques de los Sabuesos Acechadores aplican el estado acumulable de corrosión, el cual hace que todos los miembros del equipo pierdan Vida continuamente. Además, cuando reciben un ataque elemental, entran en el estado de devoración elemental, con el que se vuelven extremadamente violentos a costa de reducir su propia resistencia a ese elemento.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Garra oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112056.png","rareza":2},{"nombre":"Garra afilada oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112057.png","rareza":3},{"nombre":"Garra fantasmal oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112058.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22070101', 'genshin-impact', 'Soldado del Vacío - Abanderado', 'Shadowy Husk: Standard Bearer', 'esbirro', 'elite', 'Abismo', 'Un soldado sombrío que, en el pasado, fue un orgulloso militar de un antiguo reino subterráneo. En la actualidad, ha perdido toda conciencia y memoria.
Aun así, sigue izando el estandarte de la realeza para luchar. Ha olvidado cómo eran sus compañeros y ha perdido las bendiciones de la realeza, pero jamás bajará su estandarte.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_ForlornVessel_Strong_Warbanner_Fire.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":30},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un misterioso soldado con bandera. Cuando golpea a un personaje protegido por un escudo con sus ataques, consume cierta cantidad de su propia Vida para crear protecciones para sí mismo y para los Soldados del Vacío y Caballeros Serpiente Negra cercanos.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Estatuilla oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112017.png","rareza":2},{"nombre":"Estatuilla del amanecer","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112018.png","rareza":3},{"nombre":"Estatuilla de las profundidades","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112019.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22070301', 'genshin-impact', 'Soldado del Vacío - Defensor', 'Shadowy Husk: Defender', 'esbirro', 'elite', 'Abismo', 'Un soldado sombrío que, en el pasado, fue un orgulloso militar de un antiguo reino subterráneo. En la actualidad, no es más que una armadura vacía cuyo único recuerdo es el de luchar.
Lo peor que le puede pasar a un ser vivo es involucionar. En el caso de este cascarón vacío, su aspecto ha cambiado por la erosión que los Caballeros Serpiente Negra sufrieron a causa de sus pecados, sus maldiciones y el tiempo.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_ForlornVessel_Strong_Chargebow_Ice.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":30},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un misterioso arquero. Cuando golpea a un personaje protegido por un escudo con sus ataques, su arma se transforma durante cierto tiempo en un escudo resistente al daño y consume cierta cantidad de su propia Vida para aumentar su ATQ durante este estado. El aumento de ATQ que el Soldado del Vacío - Defensor adquiere de esta manera se puede acumular varias veces.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Estatuilla oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112017.png","rareza":2},{"nombre":"Estatuilla del amanecer","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112018.png","rareza":3},{"nombre":"Estatuilla de las profundidades","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112019.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-22070201', 'genshin-impact', 'Soldado del Vacío - Rompefilas', 'Shadowy Husk: Line Breaker', 'esbirro', 'elite', 'Abismo', 'Un soldado sombrío que, en el pasado, fue un orgulloso militar de un antiguo reino subterráneo. En la actualidad, ya no posee la razón característica de los humanos.
Parece que en su armadura vacía está grabada a fuego la voluntad de aniquilar al enemigo y de romper las filas enemigas con tal de proteger a los suyos. Sin embargo, ya nadie puede decirle dónde están esos enemigos o qué es lo que tiene que proteger.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_ForlornVessel_Strong_Lance_Water.png', '[]'::jsonb, '[{"elemento":"Físico","valor":30},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":30},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un misterioso lancero. Cuando golpea a un personaje protegido por un escudo con sus ataques, consume cierta cantidad de su propia Vida para liberar una onda curativa que regenera Vida continuamente para sí mismo y para los Soldados del Vacío y Caballeros Serpiente Negra cercanos. Este efecto de regeneración de Vida puede acumularse varias veces.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Estatuilla oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112017.png","rareza":2},{"nombre":"Estatuilla del amanecer","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112018.png","rareza":3},{"nombre":"Estatuilla de las profundidades","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112019.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-23050101', 'genshin-impact', 'Soldado Fatui - Doncella del Espejo', 'Mirror Maiden', 'esbirro', 'elite', 'Fatui', 'Una doncella Fatui que pelea utilizando espejos de agua y siempre mantiene una digna compostura, como si estuviera postrada ante un dios.
Controla los espejos de agua con una gracia resoluta, de tal modo que sus espectadores son atraídos a su espejismo. Es como si nada se escapara de sus oídos. No se sabe lo que en realidad ve detrás de esa mirada nublada, ni tampoco el siguiente movimiento que planea...', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Fatuus_Maiden_Water.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":50},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":["Físico"],"resistencias":[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":50},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":50},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[{"nombre":"Consejo de combate","descripcion":"Una doncella Fatui que utiliza un espejo de agua para combatir. Al atacar con algunas de sus habilidades, colocará sobre tu personaje una marca de refracción. Cuando un personaje afectado por este estado se encuentre cerca de la Doncella del Espejo, esta entrará en el estado de polarización y se volverá más fuerte.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Prisma oscuro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112050.png","rareza":2},{"nombre":"Prisma de cristal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112051.png","rareza":3},{"nombre":"Prisma polarizador","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112052.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-23040101', 'genshin-impact', 'Soldado Fatui - Maga de Cicin Cryo', 'Fatui Cryo Cicin Mage', 'esbirro', 'elite', 'Fatui', 'Una maga que combate mediante el control de Cicines Cryo. Sus orígenes y su rostro son un misterio.
Sin una Visión, no es posible controlar los elementos como estas Magas, pero en realidad lo que ellas hacen es usar Hierba neblinosa para manipular a los Cicines Cryo y malgastar impunemente el poder del hielo. Por otra parte, siempre están deambulando por todas partes sin ningún rumbo. ¿Cuál será su verdadera misión?', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Fatuus_Mage_Ice_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":50},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":["Físico"],"resistencias":[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":50},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":50},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Polen neblinoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112026.png","rareza":2},{"nombre":"Hierba neblinosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112027.png","rareza":3},{"nombre":"Lámpara de hierba neblinosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112028.png","rareza":4},{"nombre":"Insignia del recluta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112032.png","rareza":1},{"nombre":"Insignia del sargento","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112033.png","rareza":2},{"nombre":"Insignia del oficial","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112034.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-23030101', 'genshin-impact', 'Soldado Fatui - Maga de Cicin Electro', 'Fatui Electro Cicin Mage', 'esbirro', 'elite', 'Fatui', 'Una maga que combate mediante el control de Cicines Electro. Sus orígenes y su rostro son un misterio.
Aprovecha la afición de los Cicines voladores por la Hierba neblinosa para controlarlos y usarlos en la batalla. Igual que los Cicines Electro se embriagan con la fragancia de la Hierba neblinosa, las malvadas magas también ansían experimentar el placer de jugar con sus enemigos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Fatuus_Summoner_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":50},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Polen neblinoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112026.png","rareza":2},{"nombre":"Hierba neblinosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112027.png","rareza":3},{"nombre":"Lámpara de hierba neblinosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112028.png","rareza":4},{"nombre":"Insignia del recluta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112032.png","rareza":1},{"nombre":"Insignia del sargento","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112033.png","rareza":2},{"nombre":"Insignia del oficial","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112034.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"ht